import{_ as a,o as r,c as t,au as o}from"./chunks/framework.BTTEhLNX.js";const f=JSON.parse('{"title":"krawler","description":"A minimalist geospatial ETL","frontmatter":{"title":"krawler","description":"A minimalist geospatial ETL"},"headers":[],"relativePath":"packages/krawler/index.md","filePath":"packages/krawler/index.md"}'),s={name:"packages/krawler/index.md"};function n(i,e,l,d,c,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="krawler" tabindex="-1">krawler <a class="header-anchor" href="#krawler" aria-label="Permalink to &quot;krawler&quot;">​</a></h1><p><em>A minimalist (geospatial) ETL.</em></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Krawler aims at making the automated process of extracting and processing (geographic) data from heterogeneous sources easy. It can be viewed as a minimalist <strong>Extract, Transform, Load</strong> (ETL). <a href="https://en.wikipedia.org/wiki/Extract,_transform,_load" target="_blank" rel="noreferrer"><strong>ETL</strong></a> refers to a process where data is</p><ol><li><strong>extracted</strong> from heterogeneous data sources (e.g. databases or web services);</li><li><strong>transformed</strong> in a target format or structure for the purposes of querying and analysis (e.g. JSON or CSV);</li><li><strong>loaded</strong> into a final target data store (e.g. a file system or a database).</li></ol><p>ETL naturally leads to the concept of a <strong>pipeline</strong>: a set of processing functions (called <strong>hooks</strong> in krawler) connected in series, often executed in parallel, where the output of one function is the input of the next one. The execution of a given pipeline on an input dataset to produce the associated output is a <strong>job</strong> performed by krawler.</p>',6)])])}const m=a(s,[["render",n]]);export{f as __pageData,m as default};
